// Generated by OSL (@osl/backend-hono-trpc-vite). File storage: the local disk, or an S3-compatible bucket when S3_BUCKET is set.
// Do not edit: this file is rewritten on every osl generate.

import { createReadStream, createWriteStream } from "node:fs";
import { mkdir, stat, unlink, writeFile } from "node:fs/promises";
import path from "node:path";
import { Readable } from "node:stream";
import { pipeline } from "node:stream/promises";

export type StorageKind = "local" | "s3";

// OSL_STORAGE=local|s3 picks the adapter; without it, S3 when S3_BUCKET is set, else the local disk.
// Local: OSL_STORAGE_DIR (default ./storage). S3: S3_BUCKET, S3_REGION (default us-east-1), S3_ENDPOINT (R2, MinIO,
// Supabase), S3_ACCESS_KEY_ID, S3_SECRET_ACCESS_KEY, S3_FORCE_PATH_STYLE=true for MinIO and Supabase.
const kind: StorageKind = (process.env.OSL_STORAGE as StorageKind | undefined) ?? (process.env.S3_BUCKET ? "s3" : "local");
const localDir = process.env.OSL_STORAGE_DIR ?? "./storage";
const UPLOAD_URL_SECONDS = 900;
const DOWNLOAD_URL_SECONDS = 300;

export function storageKind(): StorageKind {
  return kind;
}

export interface UploadTarget {
  url: string;
  method: "PUT";
  headers: Record<string, string>;
}

/** Where a client PUTs a file's bytes: back to this API for local storage, a presigned URL for S3. */
export async function uploadTarget(key: string, type: string, localUrl: string): Promise<UploadTarget> {
  if (kind === "local") return { url: localUrl, method: "PUT", headers: { "content-type": type } };
  const { PutObjectCommand } = await s3();
  const url = await presign(new PutObjectCommand({ Bucket: bucket(), Key: key, ContentType: type }), UPLOAD_URL_SECONDS);
  return { url, method: "PUT", headers: { "content-type": type } };
}

/** The size of the stored bytes, or null when nothing was uploaded yet. */
export async function objectSize(key: string): Promise<number | null> {
  if (kind === "local") {
    try {
      return (await stat(localPath(key))).size;
    } catch {
      return null;
    }
  }
  const { HeadObjectCommand } = await s3();
  try {
    const head = await (await client()).send(new HeadObjectCommand({ Bucket: bucket(), Key: key }));
    return head.ContentLength ?? 0;
  } catch {
    return null;
  }
}

/** Local storage only: write an uploaded body and answer its size. */
export async function putLocal(key: string, body: ReadableStream<Uint8Array> | Uint8Array | null): Promise<number> {
  const target = localPath(key);
  await mkdir(path.dirname(target), { recursive: true });
  if (!body) {
    await writeFile(target, new Uint8Array());
    return 0;
  }
  if (body instanceof Uint8Array) {
    await writeFile(target, body);
    return body.byteLength;
  }
  await pipeline(Readable.fromWeb(body as never), createWriteStream(target));
  return (await stat(target)).size;
}

/** Local storage only: the stored bytes as a stream. */
export function readLocal(key: string): Readable {
  return createReadStream(localPath(key));
}

/** Whether a browser may show the type inline; everything else downloads. */
export function inlineType(type: string): boolean {
  return type.startsWith("image/") || type === "application/pdf" || type.startsWith("video/") || type.startsWith("audio/");
}

export function contentDisposition(name: string, type: string): string {
  const safe = name.replace(/[^\x20-\x7e]/g, "_").replace(/["\\]/g, "_");
  return `${inlineType(type) ? "inline" : "attachment"}; filename="${safe}"; filename*=UTF-8''${encodeURIComponent(name)}`;
}

/** S3 only: a short-lived URL that serves the bytes with the right type and disposition. */
export async function downloadUrl(key: string, name: string, type: string): Promise<string> {
  const { GetObjectCommand } = await s3();
  return presign(
    new GetObjectCommand({
      Bucket: bucket(),
      Key: key,
      ResponseContentType: type,
      ResponseContentDisposition: contentDisposition(name, type)
    }),
    DOWNLOAD_URL_SECONDS
  );
}

export async function remove(key: string): Promise<void> {
  if (kind === "local") {
    await unlink(localPath(key)).catch(() => {});
    return;
  }
  const { DeleteObjectCommand } = await s3();
  await (await client()).send(new DeleteObjectCommand({ Bucket: bucket(), Key: key }));
}

function localPath(key: string): string {
  const resolved = path.resolve(localDir, key);
  if (!resolved.startsWith(path.resolve(localDir) + path.sep)) throw new Error("invalid storage key");
  return resolved;
}

function bucket(): string {
  const name = process.env.S3_BUCKET;
  if (!name) throw new Error("S3_BUCKET is not set");
  return name;
}

type S3Module = typeof import("@aws-sdk/client-s3");
let s3Module: Promise<S3Module> | null = null;
function s3(): Promise<S3Module> {
  return (s3Module ??= import("@aws-sdk/client-s3"));
}

let s3Client: import("@aws-sdk/client-s3").S3Client | null = null;
async function client(): Promise<import("@aws-sdk/client-s3").S3Client> {
  if (s3Client) return s3Client;
  const { S3Client } = await s3();
  s3Client = new S3Client({
    region: process.env.S3_REGION ?? "us-east-1",
    endpoint: process.env.S3_ENDPOINT || undefined,
    forcePathStyle: process.env.S3_FORCE_PATH_STYLE === "true",
    credentials:
      process.env.S3_ACCESS_KEY_ID && process.env.S3_SECRET_ACCESS_KEY
        ? { accessKeyId: process.env.S3_ACCESS_KEY_ID, secretAccessKey: process.env.S3_SECRET_ACCESS_KEY }
        : undefined
  });
  return s3Client;
}

async function presign(command: object, expiresIn: number): Promise<string> {
  const [{ getSignedUrl }, s3Client] = await Promise.all([import("@aws-sdk/s3-request-presigner"), client()]);
  return getSignedUrl(s3Client, command as never, { expiresIn });
}
